async def cleanup(self) -> None:
    """Run cleanup for all generator-based dependencies (in reverse order)."""
    for gen in reversed(self._generators):
        try:
            if isinstance(gen, AsyncGenerator):
                try:
                    await gen.__anext__()
                except StopAsyncIteration:
                    pass
            elif isinstance(gen, Generator):
                try:
                    next(gen)
                except StopIteration:
                    pass
        except Exception:
            logger.debug("Dependency cleanup error", exc_info=True)
    self._generators.clear()
    self._cache.clear()

async def execute(self) -> None:
    """Run all queued tasks sequentially.

    Errors are logged and swallowed — they never reach the client.
    """
    for func, args, kwargs in self._tasks:
        try:
            result = func(*args, **kwargs)
            if asyncio.iscoroutine(result):
                await result
        except Exception:
            logger.exception(
                "Background task %s failed",
                getattr(func, "__name__", repr(func)),
            )
    self._tasks.clear()

def _get_key(self, ctx: RequestContext) -> str:
    if self._key_func:
        return self._key_func(ctx)
    parts: list[str] = []
    if ctx.client_id:
        parts.append(ctx.client_id)
    else:
        parts.append("global")
    if self._per_tool:
        parts.append(ctx.tool_name)
    return ":".join(parts)

async def __call__(self, ctx: RequestContext, call_next: Callable[..., Any]) -> Any:
    key = self._get_key(ctx)
    allowed, retry_after = self._limiter.consume(key)
    if not allowed:
        raise RateLimitError(retry_after=retry_after)
    return await call_next(ctx)

