async def stop(self) -> None:
    """Gracefully stop all workers."""
    if self._shutdown_event is not None:
        self._shutdown_event.set()
    for task in self._workers:
        task.cancel()
    if self._workers:
        await asyncio.gather(*self._workers, return_exceptions=True)
    self._workers.clear()
    if self._cleanup_task is not None:
        self._cleanup_task.cancel()
        try:
            await self._cleanup_task
        except asyncio.CancelledError:
            pass
        self._cleanup_task = None
    logger.info("Queue stopped")

async def _worker_loop(self, *, worker_id: int) -> None:
    """Single worker: dequeue jobs and execute them."""
    while True:
        try:
            if self._shutdown_event and self._shutdown_event.is_set():
                break

            job = await self._backend.dequeue()
            if job is None:
                await asyncio.sleep(0.1)
                continue

            await self._execute_job(job, worker_id=worker_id)

        except asyncio.CancelledError:
            break
        except Exception:
            logger.debug(
                "Worker %d encountered unexpected error",
                worker_id,
                exc_info=True,
            )
            await asyncio.sleep(1.0)

async def _cleanup_loop(self) -> None:
    """Periodically remove completed/failed jobs past their TTL."""
    try:
        while True:
            await asyncio.sleep(self._cleanup_interval)
            await self._cleanup_expired()
    except asyncio.CancelledError:
        pass

async def _cleanup_expired(self) -> None:
    """Remove terminal jobs older than result_ttl."""
    terminal = [
        JobStatus.COMPLETED,
        JobStatus.FAILED,
        JobStatus.CANCELLED,
        JobStatus.TIMEOUT,
    ]
    now = time.monotonic()
    for status in terminal:
        jobs = await self._backend.list_jobs(status=status, limit=1000)
        for job in jobs:
            if job.completed_at and (now - job.completed_at) > self._result_ttl:
                await self._backend.remove(job.id)

@server.tool(name=name, description=description)
async def _batch_call(calls: list[dict[str, Any]]) -> list[dict[str, Any]]:
    # Propagate the caller's auth context to sub-calls.
    # get_context() returns the full RequestContext (not just client info).
    from ._context import get_context

    parent_ctx = get_context()
    meta = {}
    if parent_ctx is not None:
        meta = dict(parent_ctx.meta) if parent_ctx.meta else {}

    # Enforce max batch size — reject oversized requests
    max_batch = max_parallel * 2
    if len(calls) > max_batch:
        return [
            {"status": "error", "error": f"Batch size {len(calls)} exceeds max {max_batch}"}
        ]

    client = TestClient(server, meta=meta)
    sem = asyncio.Semaphore(max_parallel)

    async def _run_one(call: dict[str, Any]) -> dict[str, Any]:
        tool_name = call.get("tool", "")
        args = call.get("args", {})
        async with sem:
            try:
                result = await client.call_tool(tool_name, args)
                return {
                    "tool": tool_name,
                    "status": "ok",
                    "result": [r.text if hasattr(r, "text") else str(r) for r in result],
                }
            except Exception as exc:
                return {
                    "tool": tool_name,
                    "status": "error",
                    "error": str(exc),
                }

    tasks = [_run_one(c) for c in calls[:max_batch]]
    results = await asyncio.gather(*tasks, return_exceptions=False)
    return list(results)

async def readiness(self) -> str:
    """Return readiness probe result as JSON string."""
    results: dict[str, Any] = {}
    all_ready = True

    for name, check, required in self._checks:
        try:
            result = check()
            if asyncio.iscoroutine(result):
                result = await result
            healthy = bool(result)
        except Exception as exc:
            healthy = False
            results[name] = {"healthy": False, "error": str(exc)}
            if required:
                all_ready = False
            continue

        results[name] = {"healthy": healthy}
        if required and not healthy:
            all_ready = False

    return json.dumps(
        {
            "status": "ready" if all_ready else "not_ready",
            "checks": results,
        }
    )

