            f"\n**Initial Answer{label}**: Provide your best answer.\n"
            f"**Critique{label}**: Identify flaws, gaps, or improvements.\n"
            f"**Improved Answer{label}**: Revise based on your critique.\n"
        )
    return (
        f"{prompt_text}\n\n"
        "Follow this self-critique process:\n"
        f"{critique_block}\n"
        f"After all rounds, write '{_ANSWER_MARKER}' on its own line, "
        "then provide your final, best answer."
    )

def parse(self, raw_output: str, ctx: PromptContext) -> str:
    if _ANSWER_MARKER in raw_output:
        return raw_output.split(_ANSWER_MARKER, 1)[1].strip()
    # Fallback: look for the last "Improved Answer" section
    parts = re.split(r"\*\*Improved Answer[^*]*\*\*:\s*", raw_output, flags=re.IGNORECASE)
    if len(parts) > 1:
        return parts[-1].strip()
    return raw_output

# Always drop dangerous capabilities.  If allow_sudo is True,
# add back only CAP_SETUID/CAP_SETGID for sudo functionality.
# CAP_SYS_ADMIN is NEVER re-added — it enables mount, ptrace,
# BPF, and namespace manipulation which are container escape vectors.
host_config["cap_drop"] = list(DEFAULT_CAP_DROP)
if self.config.allow_sudo:
    for cap in ("SETUID", "SETGID"):
        if cap in host_config["cap_drop"]:
            host_config["cap_drop"].remove(cap)

# gVisor runtime
if self.config.backend == "gvisor" or self.config.runtime == "runsc":
    host_config["runtime"] = "runsc"

# Tmpfs mounts for writable directories (when using read-only rootfs)
if host_config.get("read_only"):
    host_config["tmpfs"] = {
        "/tmp": "rw,noexec,nosuid,size=1g",  # nosec B108 - path inside sandboxed container, not host
        "/var/tmp": "rw,noexec,nosuid,size=512m",  # nosec B108 - path inside sandboxed container, not host
        self.config.workdir: "rw,size=5g",
    }

# AppArmor (only if profile is loaded on the system)
if self._check_apparmor_available():
    security_opt.append("apparmor=promptise-sandbox")

timeout = timeout or self.config.timeout
workdir = workdir or self.config.workdir

return await self.backend.execute_command(
    self.container_id, command, timeout=timeout, workdir=workdir
)

except FileNotFoundError:
    return f"ERROR: File not found: {file_path}"
except Exception as e:
    return f"ERROR: Failed to read file: {str(e)}"

except Exception as e:
    return CommandResult(
        exit_code=-1,
        stdout="",
        stderr=f"Execution failed: {str(e)}",
        timeout=False,
        duration=0.0,
    )

# Health check
if not await self.backend.health_check():
    raise RuntimeError(
        f"Sandbox backend '{self.config.backend}' is not available. "
        f"Please ensure Docker is installed and running."
    )

try:
    client = await self._get_client()
    client.ping()

    # If gVisor/runsc is requested, verify it's available
    if self.config.backend == "gvisor" or self.config.runtime == "runsc":
        return await self._verify_gvisor_available(client)

    return True
except Exception:
    return False

async def __aenter__(self) -> MCPMultiClient:
    """Connect to all servers."""
    for name, client in self._clients.items():
        try:
            await client.__aenter__()
        except Exception as exc:
            # Clean up already-connected clients
            for prev_name, prev_client in self._clients.items():
                if prev_name == name:
                    break
                try:
                    await prev_client.__aexit__(None, None, None)
                except Exception:
                    logger.debug(
                        "Error cleaning up previously connected client '%s'",
                        prev_name,
                        exc_info=True,
                    )
            raise MCPClientError(f"Failed to connect to server '{name}': {exc}") from exc
    self._connected = True
    return self

_promptise_multi = MCPMultiClient(clients)
await _promptise_multi.__aenter__()
try:
    discovered = await adapter.as_langchain_tools()
    tools = list(discovered) if discovered else []
except MCPClientError as exc:
    # Clean up on failure
    try:
        await _promptise_multi.__aexit__(None, None, None)
    except Exception:
        logger.debug("MCP multi-client cleanup error", exc_info=True)
    _promptise_multi = None
    raise RuntimeError(
        f"Failed to initialize agent because tool discovery failed. Details: {exc}"
    ) from exc

# Validate extension
if not cls._is_superagent_file(path):
    raise SuperAgentError(
        f"Invalid file extension. Expected .superagent, "
        f".superagent.yaml, or .superagent.yml. Got: {path.name}"
    )

# Load YAML
try:
    with path.open("r", encoding="utf-8") as f:
        raw_data = yaml.safe_load(f)
except yaml.YAMLError as exc:
    raise SuperAgentError(f"YAML parse error in {path}: {exc}") from exc
except Exception as exc:
    raise SuperAgentError(f"Failed to read {path}: {exc}") from exc

if not isinstance(raw_data, dict):
    raise SuperAgentError(
        f"Invalid YAML format in {path}: expected dict, got {type(raw_data)}"
    )

# Validate schema
try:
    schema = SuperAgentSchema.model_validate(raw_data)
except ValidationError as exc:
    raise SuperAgentValidationError(
        f"Schema validation failed for {path}",
        errors=[dict(e) for e in exc.errors()],
        file_path=str(path),
    ) from exc

ref_path = (self.file_path.parent / config.file).resolve()

# Check for circular reference
if ref_path in self._loading_chain:
    chain_str = " -> ".join(str(p) for p in self._loading_chain)
    raise SuperAgentError(
        f"Circular cross-agent reference detected: {chain_str} -> {ref_path}"
    )

# Load referenced agent
new_chain = self._loading_chain | {ref_path}
try:
    cross_loader = SuperAgentLoader.from_file(
        ref_path,
        _loading_chain=new_chain,
    )
